package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.Arrays;
import java.util.Comparator;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.history.SheetAsOf;
import net.officefloor.hq.app.history.SheetHistory;
import net.officefloor.hq.app.holiday.HolidayService;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonNotFoundException;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.person.PersonWatch;
import net.officefloor.hq.app.person.PersonWatchRepository;
import net.officefloor.hq.app.period.Period;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.settings.Action;
import net.officefloor.hq.app.settings.Role;
import net.officefloor.hq.app.settings.SettingsService;
import net.officefloor.hq.app.sheet.SheetService;
import net.officefloor.hq.app.voidreason.VoidReasonService;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** The claims people on each sheet make. A claim left without a date is dated the sheet's entry date,
 * or its today when that is off. A claim's
 * terms are fixed when it is added, from those of its person's grade in force on its date, and its due-by
 * is the terms-th business day after that date, skipping weekends and the holidays on the sheet when it is added; the
 * claim belongs to the period containing that due-by (not its date). Only a DRAFT claim can be edited.
 * No claim whose due-by falls inside a closed period (not only soft-closed) can be added, edited or
 * change status, nor be edited to a date whose due-by, with its terms, would; one added with its due-by inside a soft-closed period is a late entry, and none can be added or edited to a date after its person's retirement date. A claim with a
 * negative amount is a correction: it is refused unless it names, by number, a SETTLED claim of the same
 * person, and for no more than what remains of it (its amount less the corrections already made against
 * it, VOID and DELETED ones left out); a claim that is not a correction names none. A DRAFT claim may have lines (see {@link ClaimLine}):
 * then its amount is what they add up to, and an edit to any other amount is refused. */
@Service
public class ClaimService {

    private final ClaimRepository claims;
    private final ClaimLogRepository logs;
    private final ClaimCommentRepository comments;
    private final ClaimLineRepository lines;
    private final ClaimShareRepository shares;
    private final PersonRepository people;
    private final RollupService rollup;
    private final SheetService sheets;
    private final PeriodRepository periods;
    private final SettingsService settings;
    private final PersonWatchRepository watches;
    private final HolidayService holidays;
    private final Audit audit;
    private final SheetTagRepository tagRepository;
    private final VoidReasonService voidReasons;
    private final SheetHistory history;

    public ClaimService(ClaimRepository claims, ClaimLogRepository logs, PersonRepository people, RollupService rollup, SheetService sheets,
            PeriodRepository periods, SettingsService settings, PersonWatchRepository watches, HolidayService holidays,
            Audit audit, SheetTagRepository tagRepository, VoidReasonService voidReasons,
            ClaimCommentRepository comments, ClaimLineRepository lines, ClaimShareRepository shares,
            SheetHistory history) {
        this.history = history;
        this.shares = shares;
        this.comments = comments;
        this.lines = lines;
        this.voidReasons = voidReasons;
        this.tagRepository = tagRepository;
        this.holidays = holidays;
        this.watches = watches;
        this.claims = claims;
        this.logs = logs;
        this.people = people;
        this.rollup = rollup;
        this.sheets = sheets;
        this.periods = periods;
        this.settings = settings;
        this.audit = audit;
    }

    /** The sheet's claims, newest first. */
    @Transactional(readOnly = true)
    public List<Claim> list(String sheetId) {
        return claims.findBySheetIdOrderByListedDescIdDesc(sheetId);
    }

    /** The sheet's duplicate claims: for each person, date and amount with two or more claims (VOID and
     * DELETED ones left out), one line {@code <name> <date> <amount> x<count>}; people in list order, then
     * by date, then by amount. */
    @Transactional(readOnly = true)
    public List<String> duplicates(String sheetId) {
        record Key(LocalDate date, BigDecimal amount) {}
        Map<Long, Map<Key, Long>> counts = claims.findBySheetIdOrderByListedDescIdDesc(sheetId).stream()
                .filter(c -> c.getStatus() != ClaimStatus.VOID && c.getStatus() != ClaimStatus.DELETED)
                .collect(Collectors.groupingBy(Claim::getPersonId, Collectors.groupingBy(
                        c -> new Key(c.getDate(), c.getAmount().setScale(2, RoundingMode.UNNECESSARY)),
                        Collectors.counting())));
        List<String> out = new ArrayList<>();
        for (Person person : people.findBySheetIdOrderByPositionAscIdAsc(sheetId)) {
            counts.getOrDefault(person.getId(), Map.of()).entrySet().stream()
                    .filter(e -> e.getValue() >= 2)
                    .sorted(Map.Entry.<Key, Long>comparingByKey(Comparator.comparing(Key::date)
                            .thenComparing(Key::amount)))
                    .forEach(e -> out.add(person.getName() + " " + e.getKey().date() + " "
                            + e.getKey().amount().toPlainString() + " x" + e.getValue()));
        }
        return out;
    }

    /** The status logs of the claims, by claim id, each oldest first. */
    @Transactional(readOnly = true)
    public Map<Long, List<ClaimLog>> logsOf(List<Claim> of) {
        if (of.isEmpty()) return Map.of();
        return logs.findByClaimIdInOrderByIdAsc(of.stream().map(Claim::getId).toList()).stream()
                .collect(Collectors.groupingBy(ClaimLog::getClaimId));
    }

    /** The day a REVIEW claim's review day must be before for it to be late: the sheet's today less its
     * review SLA; null when the sheet has no review SLA. */
    @Transactional(readOnly = true)
    public LocalDate reviewLateBefore(String sheetId) {
        Integer sla = settings.reviewSla(sheetId);
        return sla == null ? null : sheets.today(sheetId).minusDays(sla);
    }

    /** The comments on the claims, by claim id, each oldest first. */
    @Transactional(readOnly = true)
    public Map<Long, List<ClaimComment>> commentsOf(List<Claim> of) {
        if (of.isEmpty()) return Map.of();
        return comments.findByClaimIdInOrderByIdAsc(of.stream().map(Claim::getId).toList()).stream()
                .collect(Collectors.groupingBy(ClaimComment::getClaimId));
    }

    /** The lines of the claims, by claim id, each in the order they were added. */
    @Transactional(readOnly = true)
    public Map<Long, List<ClaimLine>> linesOf(List<Claim> of) {
        if (of.isEmpty()) return Map.of();
        return lines.findByClaimIdInOrderByIdAsc(of.stream().map(Claim::getId).toList()).stream()
                .collect(Collectors.groupingBy(ClaimLine::getClaimId));
    }

    /** The shares of each of the claims, in the order they were given, by claim id. */
    public Map<Long, List<ClaimShare>> sharesOf(List<Claim> of) {
        if (of.isEmpty()) return Map.of();
        return shares.findByClaimIdInOrderByIdAsc(of.stream().map(Claim::getId).toList()).stream()
                .collect(Collectors.groupingBy(ClaimShare::getClaimId));
    }

    /** Share the claim with another person on the sheet: they hold {@code share} percent (more than 0.00)
     * of what is due on it. Refused when the person is the claim's own, already holds a share of it, when
     * its shares would total more than 100.00, and when the claim is SETTLED, VOID or DELETED. */
    @Transactional
    public Claim share(String sheetId, String user, long claimId, long personId, BigDecimal share) {
        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
        if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID
                || claim.getStatus() == ClaimStatus.DELETED) {
            throw new ClaimShareException();
        }
        Person holder = people.findByIdAndSheetId(personId, sheetId).orElseThrow(PersonNotFoundException::new);
        if (share.signum() <= 0 || holder.getId().equals(claim.getPersonId())) throw new ClaimShareException();
        List<ClaimShare> held = shares.findByClaimIdOrderByIdAsc(claim.getId());
        if (held.stream().anyMatch(s -> s.getPersonId().equals(holder.getId()))) throw new ClaimShareException();
        BigDecimal total = held.stream().map(ClaimShare::getShare).reduce(share, BigDecimal::add);
        if (total.compareTo(BigDecimal.valueOf(100)) > 0) throw new ClaimShareException();
        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
                .orElseThrow(PersonNotFoundException::new);
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        ClaimShare given = shares.saveAndFlush(new ClaimShare(sheetId, claim.getId(), holder.getId(), share));
        record("CLAIM_SHARED", user, person, claim, null, "with=" + holder.getName(), "share=" + given.shareText());
        rollup.recordSince(sheetId, user, before);
        return claim;
    }

    /** Add a line to a DRAFT claim: {@code label} (not blank), {@code qty} (at least 1) of {@code unit}
     * each; the claim's amount becomes its lines' quantities times their unit amounts, added up. It counts
     * as an edit of the claim. Refused when the claim is not a DRAFT, when its due-by is in a closed period
     * and when another user's editor holds its lock. */
    @Transactional
    public Claim addLine(String sheetId, String user, long claimId, String label, int qty, BigDecimal unit) {
        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
        if (claim.isLockedFor(user, sheets.today(sheetId))) throw new ClaimLockedException();
        refuseClosed(sheetId, claim.getDueBy());
        if (claim.getStatus() != ClaimStatus.DRAFT) throw new ClaimNotEditableException();
        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
                .orElseThrow(PersonNotFoundException::new);
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        lines.saveAndFlush(new ClaimLine(claim.getId(), label, qty, unit.setScale(2)));
        List<ClaimLine> all = lines.findByClaimIdInOrderByIdAsc(List.of(claim.getId()));
        BigDecimal total = ClaimLine.totalOf(all);
        if (total.precision() - total.scale() > 10) throw new ClaimLinedAmountException();
        claim.setAmount(total);
        claim.setEditedBy(user);
        claims.flush();
        ClaimLine line = all.get(all.size() - 1);
        record("CLAIM_LINE_ADDED", user, person, claim, claim.getNumber(), "label=" + line.getLabel(),
                "qty=" + line.getQty(), "unit=" + line.unitText());
        rollup.recordSince(sheetId, user, before);
        return claim;
    }

    /** Make the claims, settled (or left PENDING) by one bulk settle, the sheet's next settle batch,
     * returning them with its number, in the order given; records BATCH_SETTLED with the batch's number,
     * how many claims it has and the frozen figures of those SETTLED added up. */
    @Transactional
    public List<Claim> settleBatch(String sheetId, String user, List<Claim> settled) {
        int batch = sheets.nextSettleBatch(sheetId);
        List<Claim> batched = settled.stream().map(c -> {
            Claim claim = claims.lockByIdAndSheetId(c.getId(), sheetId).orElseThrow(ClaimNotFoundException::new);
            claim.setSettleBatch(batch);
            return claims.save(claim);
        }).toList();
        BigDecimal total = batched.stream()
                .filter(c -> c.getStatus() == ClaimStatus.SETTLED && c.getSettledDue() != null)
                .map(Claim::getSettledDue)
                .reduce(BigDecimal.ZERO, BigDecimal::add)
                .setScale(2, RoundingMode.HALF_UP);
        audit.change("BATCH_SETTLED", sheetId, user, "batch=" + batch, "count=" + batched.size(),
                "total=" + total.toPlainString());
        return batched;
    }

    /** Comment on the claim, whatever its status: {@code text} (not blank) is kept with the user and the
     * sheet's today. */
    @Transactional
    public Claim comment(String sheetId, String user, long claimId, String text) {
        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
                .orElseThrow(PersonNotFoundException::new);
        comments.save(new ClaimComment(claim.getId(), user, sheets.today(sheetId), text));
        record("COMMENT_ADDED", user, person, claim, claim.getNumber(), "text=" + text);
        return claim;
    }

    @Transactional
    public Claim add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note,
            String corrects) {
        return add(sheetId, user, personId, amount, date, note, corrects, null);
    }

    @Transactional
    public Claim add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note,
            String corrects, String ref) {
        return add(sheetId, user, personId, amount, date, note, corrects, ref, null);
    }

